import{z as n,x as i,o as r,c as C,q as t,j as B,D as a,d as e,s,S as o,b as l}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"回归测试与版本回滚","description":"","frontmatter":{"title":"回归测试与版本回滚","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agent-regression-rollback.md","filePath":"llm/agent-regression-rollback.md","lastUpdated":1791413859000}'),d={name:"llm/agent-regression-rollback.md"};function m(p,E,f,h,F,c){const A=i("Mermaid");return r(),C("div",null,[E[2]||(E[2]=t('<h1 id="回归测试与版本回滚" tabindex="-1">回归测试与版本回滚 <a class="header-anchor" href="#回归测试与版本回滚" aria-label="Permalink to &quot;回归测试与版本回滚&quot;">​</a></h1><div class="epigraph"><p>代理没有行级 diff：提示换一个标点、供应商悄悄更新端点，行为就全域漂移；守门只能靠分布对比，回滚必须预先排练。</p><footer>—— 据提示格式敏感性的实证与持续评测的工程口径整理</footer></div><p><a href="/llm/agent-observability">上一课</a>把每条轨迹打上版本标注；本课用这些轨迹守门：变更要过回归，劣化要能回滚。代理是复合工件——系统提示、模型、工具 schema、工具实现、编排代码——任何一处漂移都改行为，而<a href="/llm/prompt-format-sensitivity">提示格式敏感</a>已经证明：把冒号换成换行就能让分数跳几个点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统软件的回归假设「变更可 diff、行为确定」，代理两条都不满足。<span class="marginnote">回归测试通俗地说就是：改完东西后把旧用例重跑一遍，确认没把原来能用的改坏——「回归」指的是老问题又回来了。传统代码改一行，diff 能告诉你影响哪几行；代理改一个标点都可能全域变行为，所以老办法不够用。</span>变更不可 diff：模型供应商把端点指向新快照，没有任何代码改动，行为全域变化；提示的一处改写影响所有下游轨迹。行为不确定：同一版本同一任务两次运行结果可能不同，单例对比的信噪比极低。于是没有回归资产的团队只剩一种策略——上线后等用户报警，而用户的报警是抽样偏差最大的信号源。回滚同样有坑：提示回滚容易，模型回滚要旧端点还在；更隐蔽的是状态不可逆——新版本已经发出的邮件、写入的数据库行，回滚代码撤销不了。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>回归资产三层</strong>。黄金任务集：从轨迹账本（<a href="/llm/agent-observability">可观测性</a>）选有代表性的任务，连同钉住的环境（镜像、commit、数据快照，<a href="/llm/agent-eval-protocol">智能体与工具评测协议</a>的协议原样适用）录成可重放用例。断言库：过程不变量比结果断言对回归更敏感——不该发的邮件没发、预算没爆、结束语义没有从「声明完成」漂成「预算耗尽」；批处理跑分用<a href="/llm/eval-harness">评测框架 lm-eval / OpenCompass</a> 类工具组织。快照对比：新旧版本各跑同一批用例，做<strong>分布对比</strong>（成功率与过程指标的分位数、失败分桶的占比移动），不做逐例 diff。<strong>变更流程</strong>按风险分级：改提示或工具 schema 是小版本，全量回归必过；换模型是大版本，先影子流量——旧版本继续服务，新版本并排跑同一批真实请求，只比对不出服务。<strong>灰度与回滚</strong>：小流量放开后盯在线指标（完成率、接管率、成本、围栏误杀），触发阈值预先写死；回滚动作按单元排练——提示秒级回滚、模型回退到旧端点、缓存随版本作废（路由侧的灰度与摘流见<a href="/llm/model-cascade-routing">模型路由与级联</a>，权重层面的原子换代见<a href="/llm/adapter-hot-swap">适配器热更新</a>）。</p>',7)),(r(),B(o,null,{default:a(()=>[s(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHG%7B%22%E5%8F%98%E6%9B%B4%E7%B1%BB%E5%9E%8B%3F%22%7D%20--%3E%7C%22%E6%8F%90%E7%A4%BA%20%2F%20%E5%B7%A5%E5%85%B7%20schema%22%7C%20MINOR%5B%22%E5%B0%8F%E7%89%88%E6%9C%AC%EF%BC%9A%E5%85%A8%E9%87%8F%E5%9B%9E%E5%BD%92%22%5D%0A%20%20CHG%20--%3E%7C%22%E6%A8%A1%E5%9E%8B%20%2F%20%E7%BC%96%E6%8E%92%E5%A4%A7%E6%94%B9%22%7C%20MAJOR%5B%22%E5%A4%A7%E7%89%88%E6%9C%AC%EF%BC%9A%E5%BD%B1%E5%AD%90%E6%B5%81%E9%87%8F%E6%AF%94%E5%AF%B9%22%5D%0A%20%20MINOR%20--%3E%7C%22%E5%88%86%E5%B8%83%E5%AF%B9%E6%AF%94%E9%80%9A%E8%BF%87%22%7C%20GRAY%5B%22%E7%81%B0%E5%BA%A6%EF%BC%9A%E5%B0%8F%E6%B5%81%E9%87%8F%E7%9B%AF%E6%8C%87%E6%A0%87%22%5D%0A%20%20MAJOR%20--%3E%7C%22%E5%90%8C%E5%88%86%E5%B8%83%22%7C%20GRAY%0A%20%20MINOR%20--%3E%7C%22%E5%8A%A3%E5%8C%96%22%7C%20BLOCK%5B%22%E6%8B%A6%E6%88%AA%E5%8F%91%E5%B8%83%22%5D%0A%20%20MAJOR%20--%3E%7C%22%E6%BC%82%E7%A7%BB%22%7C%20BLOCK%0A%20%20GRAY%20--%3E%7C%22%E8%B6%8A%E8%A7%A6%E5%8F%91%E9%98%88%E5%80%BC%22%7C%20ROLL%5B%22%E5%9B%9E%E6%BB%9A%EF%BC%9A%E6%8F%90%E7%A4%BA%2F%E6%A8%A1%E5%9E%8B%2F%E7%BC%93%E5%AD%98%E8%81%94%E5%8A%A8%22%5D%0A%20%20GRAY%20--%3E%7C%22%E8%BE%BE%E6%A0%87%22%7C%20FULL%5B%22%E5%85%A8%E9%87%8F%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=l("p",null,[e("影子流量优于纯离线回归的机制是同分布：基准集再大也是录制的分布，线上请求才是真实分布；影子跑把新旧版本放进同一条流量，指标的差就是版本的净效应，环境漂移被差分掉。"),l("span",{class:"marginnote"},"可以把它想象成医学里的对照试验：新旧两个版本「同时」接同一批真实请求，流量、时间、外部环境全一样，唯一差别是版本——于是指标的差就能干净地归到版本头上，而不是归到「今天用户变多了」这类环境因素上。")],-1)),(r(),B(o,null,{default:a(()=>[s(A,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIVE%5B%22%E7%BA%BF%E4%B8%8A%E7%9C%9F%E5%AE%9E%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20OLD%5B%22%E6%97%A7%E7%89%88%E6%9C%AC%EF%BC%9A%E7%BB%A7%E7%BB%AD%E6%9C%8D%E5%8A%A1%E7%94%A8%E6%88%B7%22%5D%0A%20%20LIVE%20--%3E%20NEW%5B%22%E6%96%B0%E7%89%88%E6%9C%AC%EF%BC%9A%E5%BD%B1%E5%AD%90%E8%BF%90%E8%A1%8C%EF%BC%8C%E4%B8%8D%E5%AF%B9%E5%A4%96%22%5D%0A%20%20OLD%20--%3E%20C%5B%22%E5%90%8C%E6%B5%81%E9%87%8F%E5%88%86%E5%B8%83%E5%AF%B9%E6%AF%94%22%5D%0A%20%20NEW%20--%3E%20C%0A%20%20C%20--%3E%20D%7B%22%E6%8C%87%E6%A0%87%E5%B7%AE%E5%BC%82%E6%98%BE%E8%91%97%E4%B8%94%E4%B8%BA%E8%B4%9F%3F%22%7D%0A%20%20D%20--%3E%7C%22%E5%90%A6%22%7C%20GO%5B%22%E6%8C%89%E7%81%B0%E5%BA%A6%E8%AE%A1%E5%88%92%E6%94%BE%E5%BC%80%22%5D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20NOGO%5B%22%E6%8B%A6%E4%B8%8B%EF%BC%9A%E5%87%80%E6%95%88%E5%BA%94%E4%B8%BA%E5%8A%A3%E5%8C%96%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p>回滚的正确性条件是状态兼容：外部世界的副作用不可撤销，所以回滚设计从<a href="/llm/agent-guardrails">安全围栏</a>的人工卡点就开了头——不可逆动作前置审批，等于给回滚保留了「外部状态还没变」的窗口。回归集自身会过拟合：对着黄金集反复调提示，等于把测试集当训练集，这是评测污染的另一种形式；对策是黄金集轮换加保留集不参与日常调试。</p><p><span class="marginnote">「模型没变」要按版本号验证而不是按信任：同一端点在供应商侧可以无公告换快照。每次发布前用固定探针任务集跑一遍，探针分数漂了，先查模型侧再查自己——这一条能省掉大半「灵异 bug」的排查时间。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>回归套件是抽检不是证明：通过只说明「这批用例没劣化」，长尾仍会翻车——在线指标与<a href="/llm/deployment-monitoring">部署后监控</a>是回归的第二道网。版本账本要包含供应商侧的隐性变更，账目维护是持续成本。全量回归有算力账：黄金集规模与回归频率要进成本预算（<a href="/llm/agent-cost-latency">成本与延迟优化</a>），用分层套件（冒烟集每次必跑、全集按周）折中。<span class="marginnote">冒烟测试借自硬件行业：新电路板通电先看冒不冒烟——只验最基本的功能没坏。冒烟集就是几十条最关键任务，几分钟跑完，每次发布必过；全集几千条按周跑，兼顾速度与覆盖。</span>生产部署的长期案例与失败模式，下一课用真实系统对账。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代理变更不可 diff、行为不确定：守门靠分布对比，不靠逐例审查。</li><li>回归资产三层：可重放黄金集、过程断言库、新旧版本同流量影子比对。</li><li>触发阈值预先写死；回滚按单元排练，提示、模型、缓存联动失效。</li><li>不可逆动作前置审批是回滚设计的一部分：外部状态未变，回滚才有意义。</li><li>黄金集要轮换：对着回归集调提示是另一种污染。</li><li>出处：据提示格式敏感性实证与持续评测口径整理，非单篇论文。</li></ul>',6))])}const u=n(d,[["render",m]]);export{D as __pageData,u as default};
